// File is one decoded GIR file. Bodies[i] is the decoded body of
// Funcs[i] (nil while not decoded, and for bodyless functions).
type File struct {
	GoVersion, GOOS, GOARCH string
	Pkg                     Package
	SymRefs                 []SymRef
	Types                   []TypeEntry
	TypeDefs                []TypeDef
	Objects                 []Object
	Init                    Init
	Funcs                   []Func
	Bodies                  []*FuncBody
	Data                    []byte

	bodies  []byte
	strings []string
	counts  [4]int
}

const (
	secSTRINGS   = 1
	secPKG       = 2
	secSYMREFS   = 3
	secTYPES     = 4
	secTYPEDEFS  = 5
	secOBJECTS   = 6
	secINIT      = 7
	secFUNCINDEX = 8
	secBODIES    = 9
	secDATA      = 10
)

// sectionIDs lists every section in wire order.
var sectionIDs = []int{secSTRINGS, secPKG, secSYMREFS, secTYPES, secTYPEDEFS, secOBJECTS, secINIT, secFUNCINDEX, secBODIES, secDATA}

var sectionNames = map[int]string{
	secSTRINGS:   "STRINGS",
	secPKG:       "PKG",
	secSYMREFS:   "SYMREFS",
	secTYPES:     "TYPES",
	secTYPEDEFS:  "TYPEDEFS",
	secOBJECTS:   "OBJECTS",
	secINIT:      "INIT",
	secFUNCINDEX: "FUNCINDEX",
	secBODIES:    "BODIES",
	secDATA:      "DATA",
}

// refSections maps a reference kind to the section it indexes.
var refSections = map[refKind]int{
	refType: secTYPES,
	refSym:  secSYMREFS,
	refObj:  secOBJECTS,
	refFn:   secFUNCINDEX,
}

func (w *Writer) writeTypedSection(f *File, id int) {
	switch id {
	case secPKG:
		w.writePackage(&f.Pkg)
	case secSYMREFS:
		w.uvarint(uint64(len(f.SymRefs)))
		for i2 := range f.SymRefs {
			w.writeSymRef(&f.SymRefs[i2])
		}
	case secTYPES:
		w.uvarint(uint64(len(f.Types)))
		for i2 := range f.Types {
			w.writeTypeEntry(&f.Types[i2])
		}
	case secTYPEDEFS:
		w.uvarint(uint64(len(f.TypeDefs)))
		for i2 := range f.TypeDefs {
			w.writeTypeDef(&f.TypeDefs[i2])
		}
	case secOBJECTS:
		w.uvarint(uint64(len(f.Objects)))
		for i2 := range f.Objects {
			w.writeObject(&f.Objects[i2])
		}
	case secINIT:
		w.writeInit(&f.Init)
	case secFUNCINDEX:
		w.uvarint(uint64(len(f.Funcs)))
		for i2 := range f.Funcs {
			w.writeFunc(&f.Funcs[i2])
		}
	default:
		panic("not a typed section")
	}
}

func (r *Reader) readTypedSection(f *File, id int) {
	switch id {
	case secPKG:
		r.readPackage(&f.Pkg)
	case secSYMREFS:
		f.SymRefs = make([]SymRef, r.count())
		for i2 := range f.SymRefs {
			r.readSymRef(&f.SymRefs[i2])
		}
	case secTYPES:
		f.Types = make([]TypeEntry, r.count())
		for i2 := range f.Types {
			r.readTypeEntry(&f.Types[i2])
		}
	case secTYPEDEFS:
		f.TypeDefs = make([]TypeDef, r.count())
		for i2 := range f.TypeDefs {
			r.readTypeDef(&f.TypeDefs[i2])
		}
	case secOBJECTS:
		f.Objects = make([]Object, r.count())
		for i2 := range f.Objects {
			r.readObject(&f.Objects[i2])
		}
	case secINIT:
		r.readInit(&f.Init)
	case secFUNCINDEX:
		f.Funcs = make([]Func, r.count())
		for i2 := range f.Funcs {
			r.readFunc(&f.Funcs[i2])
		}
	default:
		panic("not a typed section")
	}
}

func (w *Writer) writePackage(v *Package) {
	w.str(v.Path)
	w.str(v.Name)
	w.str(v.Lang)
	w.uvarint(v.Flags)
	w.uvarint(uint64(len(v.Files)))
	for i1 := range v.Files {
		w.str(v.Files[i1])
	}
	w.uvarint(uint64(len(v.Imports)))
	for i1 := range v.Imports {
		w.str(v.Imports[i1])
	}
	w.uvarint(uint64(len(v.Linknames)))
	for i1 := range v.Linknames {
		w.writeLinkname(&v.Linknames[i1])
	}
}

func (r *Reader) readPackage(v *Package) {
	v.Path = r.str()
	v.Name = r.str()
	v.Lang = r.str()
	v.Flags = r.uvarint()
	v.Files = make([]string, r.count())
	for i1 := range v.Files {
		v.Files[i1] = r.str()
	}
	v.Imports = make([]string, r.count())
	for i1 := range v.Imports {
		v.Imports[i1] = r.str()
	}
	v.Linknames = make([]Linkname, r.count())
	for i1 := range v.Linknames {
		r.readLinkname(&v.Linknames[i1])
	}
}

