func (w *Writer) writeTypeDef(v *TypeDef) {
	w.uvarint(uint64(v.Type))
	w.uvarint(uint64(v.Underlying))
	w.uvarint(uint64(len(v.Tparams)))
	for i1 := range v.Tparams {
		w.uvarint(uint64(v.Tparams[i1]))
	}
	w.uvarint(uint64(len(v.Methods)))
	for i1 := range v.Methods {
		w.writeMethod(&v.Methods[i1])
	}
	w.uvarint(uint64(len(v.Mset)))
	for i1 := range v.Mset {
		w.writeMsetEntry(&v.Mset[i1])
	}
	w.uvarint(uint64(len(v.PtrMset)))
	for i1 := range v.PtrMset {
		w.writeMsetEntry(&v.PtrMset[i1])
	}
	w.varint(v.Size)
	w.varint(v.Align)
	w.uvarint(uint64(len(v.Offsets)))
	for i1 := range v.Offsets {
		w.varint(v.Offsets[i1])
	}
}

func (r *Reader) readTypeDef(v *TypeDef) {
	v.Type = r.typeRef()
	v.Underlying = r.typeRef()
	v.Tparams = make([]TypeID, r.count())
	for i1 := range v.Tparams {
		v.Tparams[i1] = r.typeRef()
	}
	v.Methods = make([]Method, r.count())
	for i1 := range v.Methods {
		r.readMethod(&v.Methods[i1])
	}
	v.Mset = make([]MsetEntry, r.count())
	for i1 := range v.Mset {
		r.readMsetEntry(&v.Mset[i1])
	}
	v.PtrMset = make([]MsetEntry, r.count())
	for i1 := range v.PtrMset {
		r.readMsetEntry(&v.PtrMset[i1])
	}
	v.Size = r.varint()
	v.Align = r.varint()
	v.Offsets = make([]int64, r.count())
	for i1 := range v.Offsets {
		v.Offsets[i1] = r.varint()
	}
}

