func (r *Reader) readOptType() Type {
	k := r.uvarint()
	if k == 0 {
		return nil
	}
	return r.readTypeKind(k)
}

func (r *Reader) readTypeKind(k uint64) Type {
	r.enter()
	defer r.leave()
	switch k {
	case 1:
		v := &BasicType{}
		v.Kind = BasicKind(r.uvarint())
		if !v.Kind.Valid() {
			r.failf("bad BasicKind %d", v.Kind)
		}
		return v
	case 2:
		v := &PointerType{}
		v.Elem = r.typeRef()
		return v
	case 3:
		v := &SliceType{}
		v.Elem = r.typeRef()
		return v
	case 4:
		v := &ArrayType{}
		v.Len = r.uvarint()
		v.Elem = r.typeRef()
		return v
	case 5:
		v := &MapType{}
		v.Key = r.typeRef()
		v.Elem = r.typeRef()
		return v
	case 6:
		v := &ChanType{}
		v.Dir = ChanDir(r.uvarint())
		if !v.Dir.Valid() {
			r.failf("bad ChanDir %d", v.Dir)
		}
		v.Elem = r.typeRef()
		return v
	case 7:
		v := &StructType{}
		v.Fields = make([]Field, r.count())
		for i2 := range v.Fields {
			r.readField(&v.Fields[i2])
		}
		return v
	case 8:
		v := &SignatureType{}
		v.Params = make([]TypeID, r.count())
		for i2 := range v.Params {
			v.Params[i2] = r.typeRef()
		}
		v.Results = make([]TypeID, r.count())
		for i2 := range v.Results {
			v.Results[i2] = r.typeRef()
		}
		v.Variadic = r.bool()
		return v
	case 9:
		v := &InterfaceType{}
		v.Methods = make([]IfaceMethod, r.count())
		for i2 := range v.Methods {
			r.readIfaceMethod(&v.Methods[i2])
		}
		v.Embeddeds = make([]TypeID, r.count())
		for i2 := range v.Embeddeds {
			v.Embeddeds[i2] = r.typeRef()
		}
		v.Implicit = r.bool()
		return v
	case 10:
		v := &TupleType{}
		v.Elems = make([]TypeID, r.count())
		for i2 := range v.Elems {
			v.Elems[i2] = r.typeRef()
		}
		return v
	case 11:
		v := &NamedType{}
		v.Sym = r.ref(refSym)
		v.Targs = make([]TypeID, r.count())
		for i2 := range v.Targs {
			v.Targs[i2] = r.typeRef()
		}
		return v
	case 12:
		v := &TypeParamType{}
		v.Owner = r.ref(refSym)
		v.Index = r.uvarint()
		v.Name = r.str()
		v.Constraint = r.typeRef()
		return v
	case 13:
		v := &UnionType{}
		v.Terms = make([]Term, r.count())
		for i2 := range v.Terms {
			r.readTerm(&v.Terms[i2])
		}
		return v
	}
	r.failf("bad Type kind %d", k)
	return nil
}

func (w *Writer) writeStmt(x Stmt) {
	w.enter()
	defer w.leave()
	switch v := x.(type) {
	case *ExprStmt:
		w.uvarint(1)
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
	case *AssignStmt:
		w.uvarint(2)
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Op))
		w.uvarint(uint64(len(v.Lhs)))
		for i2 := range v.Lhs {
			w.writeExpr(v.Lhs[i2])
		}
		w.uvarint(uint64(len(v.Rhs)))
		for i2 := range v.Rhs {
			w.writeExpr(v.Rhs[i2])
		}
	case *DefineStmt:
		w.uvarint(3)
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(len(v.Lhs)))
		for i2 := range v.Lhs {
			w.writeExpr(v.Lhs[i2])
		}
		w.uvarint(uint64(len(v.Rhs)))
		for i2 := range v.Rhs {
			w.writeExpr(v.Rhs[i2])
		}
		w.uvarint(uint64(len(v.Fresh)))
		for i2 := range v.Fresh {
			w.uvarint(uint64(v.Fresh[i2]))
		}
	case *VarStmt:
		w.uvarint(4)
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(len(v.Locals)))
		for i2 := range v.Locals {
			w.uvarint(uint64(v.Locals[i2]))
		}
		w.uvarint(uint64(len(v.Values)))
		for i2 := range v.Values {
			w.writeExpr(v.Values[i2])
		}
	case *IncDecStmt:
		w.uvarint(5)
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
		w.bool(v.Inc)
	case *SendStmt:
		w.uvarint(6)
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Ch)
		w.writeExpr(v.Value)
	case *GoStmt:
		w.uvarint(7)
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Call)
	case *DeferStmt:
		w.uvarint(8)
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Call)
	case *ReturnStmt:
		w.uvarint(9)
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(len(v.Results)))
		for i2 := range v.Results {
			w.writeExpr(v.Results[i2])
		}
	case *BranchStmt:
		w.uvarint(10)
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Tok))
		w.optRef(v.Label)
	case *LabeledStmt:
		w.uvarint(11)
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Label))
		w.writeStmt(v.Stmt)
	case *BlockStmt:
		w.uvarint(12)
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(len(v.Stmts)))
		for i2 := range v.Stmts {
			w.writeStmt(v.Stmts[i2])
		}
	case *IfStmt:
		w.uvarint(13)
		w.uvarint(uint64(v.Pos))
		w.writeOptStmt(v.Init)
		w.writeExpr(v.Cond)
		w.uvarint(uint64(len(v.Then)))
		for i2 := range v.Then {
			w.writeStmt(v.Then[i2])
		}
		w.writeOptStmt(v.Else)
	case *SwitchStmt:
		w.uvarint(14)
		w.uvarint(uint64(v.Pos))
		w.writeOptStmt(v.Init)
		w.writeOptExpr(v.Tag)
		w.uvarint(uint64(len(v.Clauses)))
		for i2 := range v.Clauses {
			w.writeCaseClause(&v.Clauses[i2])
		}
	case *TypeSwitchStmt:
		w.uvarint(15)
		w.uvarint(uint64(v.Pos))
		w.writeOptStmt(v.Init)
		w.writeExpr(v.X)
		w.uvarint(uint64(len(v.Clauses)))
		for i2 := range v.Clauses {
			w.writeTypeClause(&v.Clauses[i2])
		}
	case *SelectStmt:
		w.uvarint(16)
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(len(v.Clauses)))
		for i2 := range v.Clauses {
			w.writeCommClause(&v.Clauses[i2])
		}
	case *ForStmt:
		w.uvarint(17)
		w.uvarint(uint64(v.Pos))
		w.writeOptStmt(v.Init)
		w.writeOptExpr(v.Cond)
		w.writeOptStmt(v.Post)
		w.uvarint(uint64(len(v.Body)))
		for i2 := range v.Body {
			w.writeStmt(v.Body[i2])
		}
		w.uvarint(uint64(len(v.PerIter)))
		for i2 := range v.PerIter {
			w.uvarint(uint64(v.PerIter[i2]))
		}
	case *RangeStmt:
		w.uvarint(18)
		w.uvarint(uint64(v.Pos))
		w.writeOptExpr(v.Key)
		w.writeOptExpr(v.Value)
		w.writeExpr(v.X)
		w.bool(v.Define)
		w.uvarint(uint64(len(v.Fresh)))
		for i2 := range v.Fresh {
			w.uvarint(uint64(v.Fresh[i2]))
		}
		w.uvarint(uint64(len(v.Body)))
		for i2 := range v.Body {
			w.writeStmt(v.Body[i2])
		}
		w.bool(v.PerIter)
	default:
		panic(fmt.Sprintf("ir: cannot encode %T as Stmt", x))
	}
}

func (w *Writer) writeOptStmt(x Stmt) {
	if x == nil {
		w.uvarint(0)
		return
	}
	w.writeStmt(x)
}

func (r *Reader) readStmt() Stmt {
	return r.readStmtKind(r.uvarint())
}

func (r *Reader) readOptStmt() Stmt {
	k := r.uvarint()
	if k == 0 {
		return nil
	}
	return r.readStmtKind(k)
}

func (r *Reader) readStmtKind(k uint64) Stmt {
	r.enter()
	defer r.leave()
	switch k {
	case 1:
		v := &ExprStmt{}
		v.Pos = r.posRef()
		v.X = r.readExpr()
		return v
	case 2:
		v := &AssignStmt{}
		v.Pos = r.posRef()
		v.Op = AssignOp(r.uvarint())
		if !v.Op.Valid() {
			r.failf("bad AssignOp %d", v.Op)
		}
		v.Lhs = make([]Expr, r.count())
		for i2 := range v.Lhs {
			v.Lhs[i2] = r.readExpr()
		}
		v.Rhs = make([]Expr, r.count())
		for i2 := range v.Rhs {
			v.Rhs[i2] = r.readExpr()
		}
		return v
	case 3:
		v := &DefineStmt{}
		v.Pos = r.posRef()
		v.Lhs = make([]Expr, r.count())
		for i2 := range v.Lhs {
			v.Lhs[i2] = r.readExpr()
		}
		v.Rhs = make([]Expr, r.count())
		for i2 := range v.Rhs {
			v.Rhs[i2] = r.readExpr()
		}
		v.Fresh = make([]uint32, r.count())
		for i2 := range v.Fresh {
			v.Fresh[i2] = r.localRef()
		}
		return v
	case 4:
		v := &VarStmt{}
		v.Pos = r.posRef()
		v.Locals = make([]uint32, r.count())
		for i2 := range v.Locals {
			v.Locals[i2] = r.localRef()
		}
		v.Values = make([]Expr, r.count())
		for i2 := range v.Values {
			v.Values[i2] = r.readExpr()
		}
		return v
	case 5:
		v := &IncDecStmt{}
		v.Pos = r.posRef()
		v.X = r.readExpr()
		v.Inc = r.bool()
		return v
	case 6:
		v := &SendStmt{}
		v.Pos = r.posRef()
		v.Ch = r.readExpr()
		v.Value = r.readExpr()
		return v
	case 7:
		v := &GoStmt{}
		v.Pos = r.posRef()
		v.Call = r.readExpr()
		return v
	case 8:
		v := &DeferStmt{}
		v.Pos = r.posRef()
		v.Call = r.readExpr()
		return v
	case 9:
		v := &ReturnStmt{}
		v.Pos = r.posRef()
		v.Results = make([]Expr, r.count())
		for i2 := range v.Results {
			v.Results[i2] = r.readExpr()
		}
		return v
	case 10:
		v := &BranchStmt{}
		v.Pos = r.posRef()
		v.Tok = BranchTok(r.uvarint())
		if !v.Tok.Valid() {
			r.failf("bad BranchTok %d", v.Tok)
		}
		v.Label = r.optLabelRef()
		return v
	case 11:
		v := &LabeledStmt{}
		v.Pos = r.posRef()
		v.Label = r.labelRef()
		v.Stmt = r.readStmt()
		return v
	case 12:
		v := &BlockStmt{}
		v.Pos = r.posRef()
		v.Stmts = make([]Stmt, r.count())
		for i2 := range v.Stmts {
			v.Stmts[i2] = r.readStmt()
		}
		return v
	case 13:
		v := &IfStmt{}
		v.Pos = r.posRef()
		v.Init = r.readOptStmt()
		v.Cond = r.readExpr()
		v.Then = make([]Stmt, r.count())
		for i2 := range v.Then {
			v.Then[i2] = r.readStmt()
		}
		v.Else = r.readOptStmt()
		return v
	case 14:
		v := &SwitchStmt{}
		v.Pos = r.posRef()
		v.Init = r.readOptStmt()
		v.Tag = r.readOptExpr()
		v.Clauses = make([]CaseClause, r.count())
		for i2 := range v.Clauses {
			r.readCaseClause(&v.Clauses[i2])
		}
		return v
	case 15:
		v := &TypeSwitchStmt{}
		v.Pos = r.posRef()
		v.Init = r.readOptStmt()
		v.X = r.readExpr()
		v.Clauses = make([]TypeClause, r.count())
		for i2 := range v.Clauses {
			r.readTypeClause(&v.Clauses[i2])
		}
		return v
	case 16:
		v := &SelectStmt{}
		v.Pos = r.posRef()
		v.Clauses = make([]CommClause, r.count())
		for i2 := range v.Clauses {
			r.readCommClause(&v.Clauses[i2])
		}
		return v
	case 17:
		v := &ForStmt{}
		v.Pos = r.posRef()
		v.Init = r.readOptStmt()
		v.Cond = r.readOptExpr()
		v.Post = r.readOptStmt()
		v.Body = make([]Stmt, r.count())
		for i2 := range v.Body {
			v.Body[i2] = r.readStmt()
		}
		v.PerIter = make([]uint32, r.count())
		for i2 := range v.PerIter {
			v.PerIter[i2] = r.localRef()
		}
		return v
	case 18:
		v := &RangeStmt{}
		v.Pos = r.posRef()
		v.Key = r.readOptExpr()
		v.Value = r.readOptExpr()
		v.X = r.readExpr()
		v.Define = r.bool()
		v.Fresh = make([]uint32, r.count())
		for i2 := range v.Fresh {
			v.Fresh[i2] = r.localRef()
		}
		v.Body = make([]Stmt, r.count())
		for i2 := range v.Body {
			v.Body[i2] = r.readStmt()
		}
		v.PerIter = r.bool()
		return v
	}
	r.failf("bad Stmt kind %d", k)
	return nil
}

func (w *Writer) writeExpr(x Expr) {
	w.enter()
	defer w.leave()
	switch v := x.(type) {
	case *ConstExpr:
		w.uvarint(1)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeConstValue(&v.Value)
	case *NilExpr:
		w.uvarint(2)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
	case *LocalExpr:
		w.uvarint(3)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Local))
	case *GlobalExpr:
		w.uvarint(4)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Obj))
	case *ExtExpr:
		w.uvarint(5)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Sym))
	case *InstExpr:
		w.uvarint(6)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Fn)
		w.uvarint(uint64(len(v.Targs)))
		for i2 := range v.Targs {
			w.uvarint(uint64(v.Targs[i2]))
		}
	case *BlankExpr:
		w.uvarint(7)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
	case *UnaryExpr:
		w.uvarint(8)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Op))
		w.writeExpr(v.X)
	case *BinaryExpr:
		w.uvarint(9)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Op))
		w.writeExpr(v.X)
		w.writeExpr(v.Y)
	case *DerefExpr:
		w.uvarint(10)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
	case *AddrExpr:
		w.uvarint(11)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
	case *RecvExpr:
		w.uvarint(12)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Ch)
		w.bool(v.CommaOk)
	case *FieldExpr:
		w.uvarint(13)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
		w.uvarint(uint64(len(v.Path)))
		for i2 := range v.Path {
			w.uvarint(v.Path[i2])
		}
	case *IndexExpr:
		w.uvarint(14)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
		w.writeExpr(v.Index)
		w.bool(v.CommaOk)
	case *SliceExpr:
		w.uvarint(15)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
		w.writeOptExpr(v.Lo)
		w.writeOptExpr(v.Hi)
		w.writeOptExpr(v.Max)
	case *TypeAssertExpr:
		w.uvarint(16)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
		w.uvarint(uint64(v.Target))
		w.bool(v.CommaOk)
	case *ConvertExpr:
		w.uvarint(17)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
		w.bool(v.Implicit)
	case *CallExpr:
		w.uvarint(18)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Fn)
		w.uvarint(uint64(len(v.Args)))
		for i2 := range v.Args {
			w.writeExpr(v.Args[i2])
		}
		w.bool(v.Spread)
	case *MethodCallExpr:
		w.uvarint(19)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Recv)
		w.uvarint(uint64(v.Method))
		w.uvarint(uint64(v.RecvType))
		w.uvarint(uint64(len(v.Targs)))
		for i2 := range v.Targs {
			w.uvarint(uint64(v.Targs[i2]))
		}
		w.uvarint(uint64(len(v.Args)))
		for i2 := range v.Args {
			w.writeExpr(v.Args[i2])
		}
		w.bool(v.Spread)
	case *IfaceCallExpr:
		w.uvarint(20)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Recv)
		w.str(v.Name)
		w.str(v.Pkg)
		w.uvarint(uint64(len(v.Args)))
		for i2 := range v.Args {
			w.writeExpr(v.Args[i2])
		}
		w.bool(v.Spread)
	case *BuiltinCallExpr:
		w.uvarint(21)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Builtin))
		w.uvarint(uint64(v.Targ))
		w.uvarint(uint64(len(v.Args)))
		for i2 := range v.Args {
			w.writeExpr(v.Args[i2])
		}
		w.bool(v.Spread)
	case *MethodValExpr:
		w.uvarint(22)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Recv)
		w.uvarint(uint64(v.Method))
		w.uvarint(uint64(v.RecvType))
		w.uvarint(uint64(len(v.Targs)))
		for i2 := range v.Targs {
			w.uvarint(uint64(v.Targs[i2]))
		}
	case *IfaceMethodValExpr:
		w.uvarint(23)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.Recv)
		w.str(v.Name)
		w.str(v.Pkg)
	case *MethodExprExpr:
		w.uvarint(24)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Method))
		w.uvarint(uint64(v.RecvType))
		w.uvarint(uint64(len(v.Targs)))
		for i2 := range v.Targs {
			w.uvarint(uint64(v.Targs[i2]))
		}
	case *IfaceMethodExprExpr:
		w.uvarint(25)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(v.Iface))
		w.str(v.Name)
		w.str(v.Pkg)
	case *StructLitExpr:
		w.uvarint(26)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(len(v.Fields)))
		for i2 := range v.Fields {
			w.writeFieldInit(&v.Fields[i2])
		}
	case *ArrayLitExpr:
		w.uvarint(27)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(len(v.Elems)))
		for i2 := range v.Elems {
			w.writeElem(&v.Elems[i2])
		}
	case *MapLitExpr:
		w.uvarint(28)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(len(v.Entries)))
		for i2 := range v.Entries {
			w.writeMapEntry(&v.Entries[i2])
		}
	case *FuncLitExpr:
		w.uvarint(29)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(uint64(len(v.Captures)))
		for i2 := range v.Captures {
			w.uvarint(uint64(v.Captures[i2]))
		}
		w.writeFuncBody(&v.Body)
	case *TupleConvertExpr:
		w.uvarint(30)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.writeExpr(v.X)
	case *DataExpr:
		w.uvarint(31)
		w.uvarint(uint64(v.Type))
		w.uvarint(uint64(v.Pos))
		w.uvarint(v.Off)
		w.uvarint(v.Len)
	default:
		panic(fmt.Sprintf("ir: cannot encode %T as Expr", x))
	}
}

func (w *Writer) writeOptExpr(x Expr) {
	if x == nil {
		w.uvarint(0)
		return
	}
	w.writeExpr(x)
}

func (r *Reader) readExpr() Expr {
	return r.readExprKind(r.uvarint())
}

func (r *Reader) readOptExpr() Expr {
	k := r.uvarint()
	if k == 0 {
		return nil
	}
	return r.readExprKind(k)
}

func (r *Reader) readExprKind(k uint64) Expr {
	r.enter()
	defer r.leave()
	switch k {
	case 1:
		v := &ConstExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		r.readConstValue(&v.Value)
		return v
	case 2:
		v := &NilExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		return v
	case 3:
		v := &LocalExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Local = r.localRef()
		return v
	case 4:
		v := &GlobalExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Obj = r.ref(refObj)
		return v
	case 5:
		v := &ExtExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Sym = r.ref(refSym)
		return v
	case 6:
		v := &InstExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Fn = r.readExpr()
		v.Targs = make([]TypeID, r.count())
		for i2 := range v.Targs {
			v.Targs[i2] = r.typeRef()
		}
		return v
	case 7:
		v := &BlankExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		return v
	case 8:
		v := &UnaryExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Op = UnOp(r.uvarint())
		if !v.Op.Valid() {
			r.failf("bad UnOp %d", v.Op)
		}
		v.X = r.readExpr()
		return v
	case 9:
		v := &BinaryExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Op = BinOp(r.uvarint())
		if !v.Op.Valid() {
			r.failf("bad BinOp %d", v.Op)
		}
		v.X = r.readExpr()
		v.Y = r.readExpr()
		return v
	case 10:
		v := &DerefExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.X = r.readExpr()
		return v
	case 11:
		v := &AddrExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.X = r.readExpr()
		return v
	case 12:
		v := &RecvExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Ch = r.readExpr()
		v.CommaOk = r.bool()
		return v
	case 13:
		v := &FieldExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.X = r.readExpr()
		v.Path = make([]uint64, r.count())
		for i2 := range v.Path {
			v.Path[i2] = r.uvarint()
		}
		return v
	case 14:
		v := &IndexExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.X = r.readExpr()
		v.Index = r.readExpr()
		v.CommaOk = r.bool()
		return v
	case 15:
		v := &SliceExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.X = r.readExpr()
		v.Lo = r.readOptExpr()
		v.Hi = r.readOptExpr()
		v.Max = r.readOptExpr()
		return v
	case 16:
		v := &TypeAssertExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.X = r.readExpr()
		v.Target = r.typeRef()
		v.CommaOk = r.bool()
		return v
	case 17:
		v := &ConvertExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.X = r.readExpr()
		v.Implicit = r.bool()
		return v
	case 18:
		v := &CallExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Fn = r.readExpr()
		v.Args = make([]Expr, r.count())
		for i2 := range v.Args {
			v.Args[i2] = r.readExpr()
		}
		v.Spread = r.bool()
		return v
	case 19:
		v := &MethodCallExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Recv = r.readExpr()
		v.Method = r.ref(refSym)
		v.RecvType = r.typeRef()
		v.Targs = make([]TypeID, r.count())
		for i2 := range v.Targs {
			v.Targs[i2] = r.typeRef()
		}
		v.Args = make([]Expr, r.count())
		for i2 := range v.Args {
			v.Args[i2] = r.readExpr()
		}
		v.Spread = r.bool()
		return v
	case 20:
		v := &IfaceCallExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Recv = r.readExpr()
		v.Name = r.str()
		v.Pkg = r.str()
		v.Args = make([]Expr, r.count())
		for i2 := range v.Args {
			v.Args[i2] = r.readExpr()
		}
		v.Spread = r.bool()
		return v
	case 21:
		v := &BuiltinCallExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Builtin = Builtin(r.uvarint())
		if !v.Builtin.Valid() {
			r.failf("bad Builtin %d", v.Builtin)
		}
		v.Targ = r.typeRef()
		v.Args = make([]Expr, r.count())
		for i2 := range v.Args {
			v.Args[i2] = r.readExpr()
		}
		v.Spread = r.bool()
		return v
	case 22:
		v := &MethodValExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Recv = r.readExpr()
		v.Method = r.ref(refSym)
		v.RecvType = r.typeRef()
		v.Targs = make([]TypeID, r.count())
		for i2 := range v.Targs {
			v.Targs[i2] = r.typeRef()
		}
		return v
	case 23:
		v := &IfaceMethodValExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Recv = r.readExpr()
		v.Name = r.str()
		v.Pkg = r.str()
		return v
	case 24:
		v := &MethodExprExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Method = r.ref(refSym)
		v.RecvType = r.typeRef()
		v.Targs = make([]TypeID, r.count())
		for i2 := range v.Targs {
			v.Targs[i2] = r.typeRef()
		}
		return v
	case 25:
		v := &IfaceMethodExprExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Iface = r.typeRef()
		v.Name = r.str()
		v.Pkg = r.str()
		return v
	case 26:
		v := &StructLitExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Fields = make([]FieldInit, r.count())
		for i2 := range v.Fields {
			r.readFieldInit(&v.Fields[i2])
		}
		return v
	case 27:
		v := &ArrayLitExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Elems = make([]Elem, r.count())
		for i2 := range v.Elems {
			r.readElem(&v.Elems[i2])
		}
		return v
	case 28:
		v := &MapLitExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Entries = make([]MapEntry, r.count())
		for i2 := range v.Entries {
			r.readMapEntry(&v.Entries[i2])
		}
		return v
	case 29:
		v := &FuncLitExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Captures = make([]uint32, r.count())
		for i2 := range v.Captures {
			v.Captures[i2] = r.localRef()
		}
		r.readFuncBody(&v.Body)
		return v
	case 30:
		v := &TupleConvertExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.X = r.readExpr()
		return v
	case 31:
		v := &DataExpr{}
		v.Type = r.typeRef()
		v.Pos = r.posRef()
		v.Off = r.uvarint()
		v.Len = r.uvarint()
		return v
	}
	r.failf("bad Expr kind %d", k)
	return nil
}
